/* Trzy niezależne propozycje w palecie biel / czerwień / czerń. */
Object.assign(themes.clear,{name:'Forma',tag:'01 / FORMA',title:'Biel, przestrzeń i jeden mocny akcent.',desc:'Najbardziej minimalistyczny kierunek. Delikatne obrysy, miękkie narożniki i czysta czerwień przy najważniejszych działaniach.',colors:['#FFFFFF','#D72631','#141414','#F5F5F5'],labels:['Biel / tło','Czerwień / akcje','Czerń / tekst','Szarość / podział'],heading:'Manrope',body:'Manrope',brand:'Miejsce na dobry początek.',rationale:'Biel dominuje na wszystkich ekranach. Szeroka siatka, cienkie linie i czerwone przyciski dają lekki, uporządkowany interfejs. Propozycja dla marki, która chce być spokojna i precyzyjna.',geometry:'Narożniki 16 px. Rytm 8 px. Bez dużych ciemnych sekcji. Jedna czerwona akcja w każdym obszarze.',voice:'Zwięźle i rzeczowo. Najpierw stanowisko, miejsce i stawka, potem szczegóły.'});
Object.assign(themes.nord,{name:'Index',tag:'02 / INDEX',title:'Mocna typografia. Wyraźny rytm.',desc:'Graficzny, modernistyczny kierunek: czarne nagłówki, numerowane branże, czerwone podkreślenia i precyzyjne linie na bieli.',colors:['#FFFFFF','#E02020','#101010','#F4F4F4'],labels:['Biel / tło','Czerwień / znak','Czerń / typografia','Szarość / pola'],heading:'Manrope',body:'DM Sans',brand:'Praca. Konkretnie.',rationale:'Najbardziej graficzny z trzech kierunków. Układ przypomina starannie zaprojektowany indeks: treść ma wyraźną kolejność, a czerwień służy orientacji. Białe tło jest częścią kompozycji.',geometry:'Narożniki 6 px. Wyraźne linie i asymetryczna siatka. Duże nagłówki, mało ramek. Numery porządkują branże.',voice:'Bez ozdobników. Jasne dane, krótkie etykiety, konkretne warunki.'});
Object.assign(themes.signal,{name:'Orbit',tag:'03 / ORBIT',title:'Miękka forma. Nowoczesny charakter.',desc:'Najbardziej zaokrąglony kierunek. Białe powierzchnie, kapsułowa nawigacja, subtelne cienie i malinowa czerwień.',colors:['#FFFFFF','#E31B42','#181818','#FFF4F6'],labels:['Biel / tło','Malinowa czerwień / akcje','Czerń / tekst','Jasny róż / drobne akcenty'],heading:'DM Sans',body:'DM Sans',brand:'Twój kolejny ruch.',rationale:'Najbardziej miękki i współczesny wariant. Rozdziela wprowadzenie od kompaktowej wyszukiwarki, nadaje ofertom formę lekkich białych kart i łączy je zaokrągloną nawigacją.',geometry:'Narożniki 28–36 px. Kapsułowe przyciski. Drobne cienie przy białych powierzchniach. Kolor pojawia się oszczędnie.',voice:'Bezpośrednio, naturalnie. „Szukaj pracy”, „Zapisz ofertę”, „Sprawdź warunki”.'});
home=function(){const headlines={clear:'Praca w Belgii.<br><em>Dobry kolejny krok.</em>',nord:'Praca.<br>Belgia.<br><em>Twój wybór.</em>',signal:'Znajdź pracę.<br><em>Zrób swój ruch.</em>'};return `${nav()}<main><section class="new-hero"><div class="hero-copy"><span class="new-kicker">Pracuj.be / Belgia</span><h1>${headlines[theme]}</h1><p>Porównaj stawki i warunki.<br>Aplikuj swoim profilem zawodowym, bez CV.</p>${theme==='nord'?'<span class="index-note">01 — SZUKAJ<br>02 — PORÓWNAJ<br>03 — APLIKUJ</span>':''}</div><div class="hero-search"><h2>Jakiej pracy szukasz?</h2>${search()}<div class="new-categories">${['Logistyka','Produkcja','Budownictwo','Technika'].map((x,i)=>`<button data-category="${x}"><span>0${i+1}</span>${x}</button>`).join('')}</div></div></section><section class="new-offers"><div class="section-head"><div><span class="new-kicker">Oferty pracy</span><h2>${theme==='nord'?'Aktualne możliwości.':'Sprawdź najnowsze oferty'}</h2></div>${button('Wszystkie oferty ↗','jobs','text-link')}</div><div class="new-job-list">${jobs.map(j=>jobCard(j)).join('')}</div></section><section class="new-profile"><div><span class="new-kicker">Twój profil zawodowy</span><h2>Liczy się to, co potrafisz.</h2><p>Dodaj doświadczenie i umiejętności. Pracodawcy mogą przesyłać Ci propozycje pracy.</p></div>${button('Zobacz profil','candidate')}</section></main>${footer()}`;};
const baseBrand=brand;
brand=function(){return baseBrand().replace('Litera „p” w prostej formie. Wersja pełna, sygnet i jednobarwna. Bez teczek, krawatów i uścisków dłoni.','Nazwa Pracuj.be, czerwień i prosty detal typograficzny. Rozpoznawalność buduje proporcja liter oraz konsekwentne użycie koloru. Wersje pełna, mała i jednobarwna.');};
const baseEmployer=employer;employer=function(){return baseEmployer().replace('Dobry zespół zaczyna się tutaj.','Twoja rekrutacja.').replace('Najważniejsze informacje o Twojej rekrutacji.','Nowe zgłoszenia, aktywne oferty i najbliższe rozmowy.');};
const baseJobs=jobList;jobList=function(){return baseJobs().replace('Znajdź swoje miejsce.','Oferty pracy w Belgii.');};
document.title='Pracuj.be — Forma, Index, Orbit';render();
